import {getLanguage} from './i18n-core.mjs';
const t=(da,en)=>getLanguage()==='en'?en:da;
export function addressPickerHTML(){return `<div class="address-picker" data-address-picker><label for="delivery-address-search">${t('Adresse *','Address *')}</label><div class="address-search-wrap"><input id="delivery-address-search" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="delivery-address-options" aria-describedby="delivery-address-help delivery-address-status" autocomplete="off" spellcheck="false" maxlength="73" required placeholder="${t('Søg på vejnavn og husnummer','Search street and house number')}"><ul id="delivery-address-options" class="address-options" role="listbox" aria-label="${t('Adresseforslag','Address suggestions')}" hidden></ul></div><p id="delivery-address-help" class="address-help">${t('Vælg din adresse fra listen – også etage og dør, hvis du bor i lejlighed.','Choose your address from the list, including floor and door for apartments.')}</p><p id="delivery-address-status" class="address-status" role="status" aria-live="polite"></p><input type="hidden" name="addressId"><input type="hidden" name="street"><div class="address-location"><label>${t('Postnummer','Postal code')}<input name="postalCode" readonly autocomplete="off" tabindex="-1"></label><label>${t('By','City')}<input name="city" readonly autocomplete="off" tabindex="-1"></label><span class="address-country">${t('Danmark','Denmark')}<input type="hidden" name="country" value="DK"></span></div><p class="address-help">${t('Kan du ikke finde adressen?','Can’t find the address?')} <a href="mailto:hello@smerch.dk">${t('Kontakt os','Contact us')}</a></p></div>`;}
export function bindAddressPicker(form,{fetchImpl=fetch}={}){
 const root=form.querySelector('[data-address-picker]');if(!root)return;
 const input=root.querySelector('[role=combobox]'),list=root.querySelector('[role=listbox]'),status=root.querySelector('[role=status]');
 let timer,controller,requestKind,version=0,active=-1,items=[];
 const message=()=>t('Vælg din fulde adresse fra forslagene.','Choose your complete address from the suggestions.');
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
 const invalidate=()=>{clearTimeout(timer);controller?.abort();version++;close();items=[];for(const key of ['addressId','street','postalCode','city'])form.elements[key].value='';input.setCustomValidity(message());status.textContent='';root.classList.remove('address-selected');};
 input.setCustomValidity(message());
 async function api(body,signal){const response=await fetchImpl('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});const data=await response.json();if(!response.ok)throw Error();return data;}
 function highlight(index){active=index;for(const [i,el] of [...list.children].entries())el.setAttribute('aria-selected',String(i===active));if(active>=0){input.setAttribute('aria-activedescendant',list.children[active].id);list.children[active].scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
 function render(data){items=data.suggestions||[];list.replaceChildren();active=-1;items.forEach((item,i)=>{const li=document.createElement('li');li.id=`delivery-address-option-${i}`;li.setAttribute('role','option');li.setAttribute('aria-selected','false');const title=document.createElement('span');title.textContent=item.label;const hint=document.createElement('small');hint.textContent=item.type==='adresse'?t('Vælg adresse','Choose address'):item.type==='husnummer'?t('Vælg etage og dør','Choose floor and door'):t('Tilføj husnummer','Add house number');li.append(title,hint);li.addEventListener('pointerdown',e=>e.preventDefault());li.addEventListener('click',()=>choose(i));list.append(li);});list.hidden=!items.length;input.setAttribute('aria-expanded',String(Boolean(items.length)));status.textContent=items.length?(data.refine?t('Skriv etage eller dør for at indsnævre listen.','Add floor or door to narrow the list.'):t('Vælg et forslag, eller skriv videre.','Choose a suggestion or keep typing.')):t('Ingen adresser fundet. Prøv med vejnavn, husnummer og postnummer.','No addresses found. Try street, house number and postal code.');}
 async function search(body){requestKind='search';controller?.abort();controller=new AbortController();const current=++version;status.textContent=t('Søger efter adresser…','Searching addresses…');try{const data=await api(body,controller.signal);if(current!==version||!root.isConnected)return;render(data);}catch(e){if(current!==version||e.name==='AbortError')return;close();status.textContent=t('Adressesøgningen er midlertidigt utilgængelig. Prøv igen, eller kontakt os nedenfor.','Address search is temporarily unavailable. Try again or contact us below.');}}
 async function choose(index){const item=items[index];if(!item)return;invalidate();input.value=item.label;input.focus();if(item.type!=='adresse'){await search(item.type==='husnummer'?{houseId:item.id}:{query:item.label});if(item.type!=='husnummer')status.textContent=t('Tilføj husnummer, og vælg din fulde adresse.','Add house number and choose your complete address.');return;}
  requestKind='resolve';const current=++version;controller=new AbortController();status.textContent=t('Kontrollerer adressen…','Checking address…');try{const address=await api({id:item.id},controller.signal);if(current!==version||!root.isConnected)return;for(const key of ['addressId','street','postalCode','city'])form.elements[key].value=address[key];input.value=address.label;input.setCustomValidity('');root.classList.add('address-selected');status.textContent=t('✓ Adresse valgt – kontrollér, at etage og dør er korrekt.','✓ Address selected – check that floor and door are correct.');close();}catch(e){if(current!==version||e.name==='AbortError')return;status.textContent=t('Adressen kunne ikke kontrolleres. Prøv at vælge den igen.','The address could not be checked. Please select it again.');}}
 input.addEventListener('input',()=>{invalidate();if(input.value.trim().length>=2)timer=setTimeout(()=>search({query:input.value}),250);});
 input.addEventListener('keydown',e=>{if(e.key==='Escape'){clearTimeout(timer);controller?.abort();version++;close();if(!form.elements.addressId.value)status.textContent='';}else if(!list.hidden&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();highlight((active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length);}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();if(active>=0)choose(active);}});
 input.addEventListener('blur',()=>{clearTimeout(timer);if(requestKind==='search'){controller?.abort();version++;if(!form.elements.addressId.value)status.textContent='';}close();});
 input.addEventListener('focus',()=>{if(!form.elements.addressId.value&&input.value.trim().length>=2)search({query:input.value});});
}
